import type { ChatStatus, FileUIPart } from "ai";
import { type ComputedRef, inject, type InjectionKey, type WritableComputedRef } from "vue";

/** What `PromptInput` shares with its parts. */
export interface PromptInputContext {
  text: WritableComputedRef<string>;
  files: ComputedRef<readonly FileUIPart[]>;
  status: ComputedRef<ChatStatus>;
  disabled: ComputedRef<boolean>;
  readonly: ComputedRef<boolean>;
  placeholder: ComputedRef<string | undefined>;
  accept: ComputedRef<string | undefined>;
  single: ComputedRef<boolean>;
  submitLabel: ComputedRef<string | undefined>;
  /** The accessible name of the field: the root's `aria-label`, else "Message". */
  label: ComputedRef<string>;
  canSubmit: ComputedRef<boolean>;
  /** Files are being read before they show. */
  preparing: ComputedRef<boolean>;
  /** A `PromptInputAttach` that is not disabled is in the prompt, so a paste can add files. */
  takesFiles: ComputedRef<boolean>;
  /** Registers a `PromptInputAttach`. The getter says whether it is disabled. Returns the function that removes it. */
  addAttach: (disabled: () => boolean) => () => void;
  addFiles: (files: FileList | Iterable<File>, onAccepted?: () => void) => Promise<void>;
  removeFile: (index: number) => void;
  /** Submits the form, as Enter does. */
  requestSubmit: () => void;
  /** The submit button: Send when ready, Stop while a reply streams, and Retry after an error. */
  press: () => void;
}

export const promptInputKey: InjectionKey<PromptInputContext> = Symbol("PromptInput");

/** The context of the `PromptInput` around a part. A part outside a `PromptInput` gets none and renders nothing. */
export function usePromptInput(): PromptInputContext | undefined {
  return inject(promptInputKey, undefined);
}

import type { FileUIPart } from "ai";

/** The files after a pick: added to the current ones, or only the last one when the prompt takes a single file. */
export function nextPromptFiles(current: readonly FileUIPart[], selected: readonly FileUIPart[], single: boolean): readonly FileUIPart[] {
  return single ? selected.slice(-1) : [...current, ...selected];
}

/** Whether a file matches an `accept` list of the file input, such as `image/*,.pdf`. */
export function matchesAccept(file: File, accept: string | undefined): boolean {
  if (!accept) return true;
  return accept.split(",").some((entry) => {
    const value = entry.trim();
    if (value.startsWith(".")) return file.name.toLowerCase().endsWith(value.toLowerCase());
    if (value.endsWith("/*")) return file.type.startsWith(value.slice(0, -1));
    return file.type === value;
  });
}

/** Reads a file into an AI SDK file part with a data URL, as the model receives it. */
export function fileToUIPart(file: File): Promise<FileUIPart> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => reject(reader.error ?? new DOMException(`Could not read ${file.name}.`, "NotReadableError"));
    reader.onload = () => resolve({ filename: file.name, mediaType: file.type || "application/octet-stream", type: "file", url: String(reader.result) });
    reader.readAsDataURL(file);
  });
}

/** Whether the device has only coarse pointers, such as a phone. A tablet with a trackpad or a mouse is not touch only. */
export function touchOnly(): boolean {
  return typeof matchMedia === "function" && matchMedia("(pointer: coarse)").matches && !matchMedia("(any-pointer: fine)").matches;
}

export { default as PromptInput } from "./PromptInput.vue";
export { default as PromptInputAttach } from "./PromptInputAttach.vue";
export { default as PromptInputAttachments } from "./PromptInputAttachments.vue";
export { default as PromptInputSubmit } from "./PromptInputSubmit.vue";
export { default as PromptInputTextarea } from "./PromptInputTextarea.vue";
export { default as PromptInputToolbar } from "./PromptInputToolbar.vue";
export { fileToUIPart, matchesAccept, nextPromptFiles } from "./files.ts";
export type * from "./types.ts";

/* PromptInput: a text box with a toolbar of round buttons. Each part is styled by its own data-slot. */
@layer components {
  [data-slot="prompt-input"] {
    width: 100%;
  }

  [data-slot="prompt-input-group"] {
    background: var(--vh-bg);
    border: 1px solid var(--vh-border);
    border-radius: calc(var(--vh-radius) * 2);
    display: flex;
    flex-direction: column;
    min-width: 0;
  }

  [data-slot="prompt-input-attachments"] {
    padding: 0.5rem 0.5rem 0;
  }

  [data-slot="prompt-input-textarea"] {
    background: transparent;
    border: 0;
    color: var(--vh-highlighted);
    field-sizing: content;
    font: inherit;
    font-size: 0.875rem;
    line-height: 1.5rem;
    max-height: 12rem;
    min-height: 3.5rem;
    padding: 0.75rem 0.875rem 0.25rem;
    resize: none;
    width: 100%;
  }

  /* iOS Safari zooms into a focused field with text under 16px. Touch screens get at least 16px, whatever the root font size; mouse-only devices keep 14px. */
  @media (any-pointer: coarse) {
    [data-slot="prompt-input-textarea"] {
      font-size: max(1rem, 16px);
    }
  }

  [data-slot="prompt-input-textarea"]::placeholder {
    color: var(--vh-muted);
  }

  [data-slot="prompt-input-toolbar"] {
    align-items: center;
    display: flex;
    gap: 0.375rem;
    min-width: 0;
    padding: 0.25rem 0.5rem 0.5rem;
  }

  [data-slot="prompt-input-spacer"] {
    flex: 1;
  }

  /* On a phone the Send button sends, so it gets a 48px target around its 32px circle without a larger circle. */
  @media (pointer: coarse) {
    [data-slot="prompt-input-toolbar"] button {
      position: relative;
    }

    [data-slot="prompt-input-toolbar"] button::before {
      content: "";
      inset: -8px;
      position: absolute;
    }
  }

  /* The attach and submit buttons: 28px circles around a 16px icon. */
  [data-slot="prompt-input-attach"],
  [data-slot="prompt-input-submit"] {
    align-items: center;
    background: transparent;
    border: 0;
    border-radius: 9999px;
    color: var(--vh-text);
    cursor: pointer;
    display: inline-flex;
    flex-shrink: 0;
    font: inherit;
    font-weight: 500;
    justify-content: center;
    padding: 0.375rem;
    transition-duration: 150ms;
    transition-property: color, background-color, border-color, box-shadow;
    transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
  }

  [data-slot="prompt-input-attach"] > svg,
  [data-slot="prompt-input-submit"] > svg {
    flex-shrink: 0;
    height: 1rem;
    width: 1rem;
  }

  [data-slot="prompt-input-attach"]:focus-visible,
  [data-slot="prompt-input-submit"]:focus-visible {
    outline: 3px solid color-mix(in oklab, var(--vh-highlighted) 25%, transparent);
    outline-offset: 0;
  }

  [data-slot="prompt-input-attach"]:disabled,
  [data-slot="prompt-input-submit"]:disabled {
    cursor: not-allowed;
    opacity: 0.75;
  }

  [data-slot="prompt-input-attach"][data-variant="outline"] {
    background: var(--vh-bg);
    box-shadow: inset 0 0 0 1px var(--vh-border-accented);
  }

  [data-slot="prompt-input-attach"][data-variant="outline"]:not(:disabled):hover {
    background: var(--vh-bg-elevated);
  }

  [data-slot="prompt-input-attach"][data-variant="ghost"] {
    color: var(--vh-muted);
  }

  [data-slot="prompt-input-attach"][data-variant="ghost"]:not(:disabled):hover {
    background: var(--vh-bg-elevated);
    color: var(--vh-text);
  }

  [data-slot="prompt-input-submit"][data-variant="solid"] {
    background: var(--vh-highlighted);
    color: var(--vh-inverted);
  }

  [data-slot="prompt-input-submit"][data-variant="solid"]:not(:disabled):hover {
    background: color-mix(in oklab, var(--vh-highlighted) 90%, transparent);
  }

  [data-slot="prompt-input-submit"][data-variant="soft"] {
    background: var(--vh-bg-elevated);
  }

  [data-slot="prompt-input-submit"][data-variant="soft"]:not(:disabled):hover {
    background: color-mix(in oklab, var(--vh-bg-accented) 75%, transparent);
  }

  [data-slot="prompt-input-submit"][data-loading] > svg {
    animation: vh-prompt-input-spin 1s linear infinite;
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="prompt-input-submit"][data-loading] > svg {
      animation-duration: 3s;
    }
  }
}

@keyframes vh-prompt-input-spin {
  to {
    transform: rotate(360deg);
  }
}

import type { ChatStatus, FileUIPart } from "ai";

export interface PromptInputProps {
  /** The text, with `v-model`. */
  modelValue?: string;
  /** The first text when `v-model` is not bound. */
  defaultValue?: string;
  /** The attached files, with `v-model:files`. */
  files?: readonly FileUIPart[];
  /** The first files when `v-model:files` is not bound. */
  defaultFiles?: readonly FileUIPart[];
  /** The chat status. While a reply streams, the submit button stops it. After an error, it retries. */
  status?: ChatStatus;
  /** The file types that the file picker shows, as in `<input accept>`. */
  accept?: string;
  /** The prompt keeps one file: a new pick replaces it. */
  single?: boolean;
  /** Takes the picked or pasted files and returns the ones to attach. */
  filterFiles?: (files: readonly File[]) => readonly File[];
  /** The prompt takes no input: the field, the attach button, Send, and Retry are disabled. Stop stays pressable. */
  disabled?: boolean;
  /** The text is being sent: the field is read-only, Enter does nothing, and Send shows a spinner. */
  readonly?: boolean;
  placeholder?: string;
  /** The name of the submit button while the status is `ready`. Default "Send prompt". */
  submitLabel?: string;
}

export interface PromptInputSubmitEvent {
  text: string;
  files: readonly FileUIPart[];
}

export interface PromptInputEmits {
  "update:modelValue": [value: string];
  "update:files": [files: readonly FileUIPart[]];
  /** Enter or Send, with the trimmed text and the files. */
  submit: [event: PromptInputSubmitEvent];
  /** Stop, while a reply streams. */
  stop: [];
  /** Retry, after an error. */
  retry: [];
  /** A file could not be read. */
  error: [event: { error: unknown }];
}

export interface PromptInputSlotScope {
  canSubmit: boolean;
  /** Files are being read before they show. */
  preparing: boolean;
  status: ChatStatus;
}

export interface PromptInputSlots {
  /**
   * Replaces the default composition: `PromptInputAttachments`, `PromptInputTextarea`, and a `PromptInputToolbar` with
   * `PromptInputAttach` and `PromptInputSubmit`. Leave out `PromptInputAttach` to turn off files.
   */
  default?: (scope: PromptInputSlotScope) => unknown;
}

export interface PromptInputAttachmentsProps {
  /** The remove buttons are disabled, for example while the files are sent. */
  disabled?: boolean;
}

export interface PromptInputAttachProps {
  /** `outline` is a ring, `ghost` a muted icon for a box that has its own frame. */
  variant?: "outline" | "ghost";
  /** Files cannot be added. Text stays editable. */
  disabled?: boolean;
  /** The accessible name of the button and the file input. */
  label?: string;
}

export interface PromptInputAttachSlots {
  /** The icon. Default: a plus. */
  default?: () => unknown;
}

export interface PromptInputSubmitSlots {
  /** The icon or the label. Default: an arrow up to send, a square to stop, and a circle arrow to retry. */
  default?: (scope: PromptInputSlotScope) => unknown;
}

export interface PromptInputToolbarSlots {
  default?: () => unknown;
}
